<script setup lang="ts">const props=defineProps<{pageSlug:string}>();const [{data:pages},{data:blocks}]=await Promise.all([useFetch('/api/public/pages',{default:()=>[]}),useFetch('/api/public/contentBlocks',{default:()=>[]})]);const page=computed(()=>pages.value.find((item:any)=>item.slug===props.pageSlug));const block=computed(()=>blocks.value.find((item:any)=>item.pageSlug===props.pageSlug&&item.type==='page-header'&&item.status==='published'));useHead(()=>({title:page.value?.seoTitle||page.value?.title||'AM Moreira',meta:[{name:'description',content:page.value?.metaDescription||''},{name:'robots',content:page.value?.indexable===false?'noindex, nofollow':'index, follow'}]}))</script><template><PublicPageHeader v-if="block" :kicker="block.eyebrow||''" :title="block.title||page?.title||''" :description="block.content||''"/></template>
